import {PRODUCTS,lineTotal} from './catalog.js';
import {cents} from './core.js';
export function initCatalog(form){
 const f=name=>form.elements.namedItem(name),titleLabel=document.querySelector('#title-label');
 const box=document.createElement('section');box.id='catalog-picker';box.innerHTML='<label>Товар из списка<input type="search" id="catalog-search" placeholder="Поиск по марке, размеру или артикулу" autocomplete="off"><select id="catalog-product" aria-label="Товар из списка"></select></label><p class="catalog-source">19 позиций · загружено вручную</p><label id="catalog-price-label" hidden>Цена за 1 шт., ₽<input id="catalog-price" inputmode="decimal" autocomplete="off"></label><p id="catalog-calculation" class="catalog-calculation" aria-live="polite"></p>';
 titleLabel.before(box);const search=box.querySelector('#catalog-search'),select=box.querySelector('#catalog-product'),price=box.querySelector('#catalog-price'),priceLabel=box.querySelector('#catalog-price-label'),hint=box.querySelector('#catalog-calculation');const qtyLabel=document.querySelector('#qty-label'),operationLabel=document.querySelector('#operation-label'),amountRow=document.querySelector('#amount-row');const lineFields=document.createElement('div');lineFields.className='catalog-line-fields';priceLabel.before(lineFields);lineFields.append(priceLabel);let selectedId='';
 const rub=value=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:value%100?2:0}).format(value/100);
 function options(){const q=search.value.trim().toLocaleLowerCase('ru');const tokens=q.split(/\s+/).filter(Boolean).map(s=>s.replaceAll('/',''));const visible=PRODUCTS.filter(p=>p.id===selectedId||tokens.every(token=>[p.title,p.article].join(' ').toLocaleLowerCase('ru').replace(/[\s/]+/g,'').includes(token)));select.replaceChildren(new Option(q?'Найдено: '+visible.length+' · выберите товар':'Выберите шину…',''),new Option('＋ Ввести товар вручную','manual'),...visible.map(p=>new Option(p.title+' — '+rub(p.unitPrice)+(p.article?' · арт. '+p.article:'')+' · №'+p.sourceRow,p.id)));select.value=selectedId;}
 function show(){const active=f('type').value==='sale';box.hidden=!active;const product=PRODUCTS.find(p=>p.id===select.value);if(active){document.querySelector('#extra').append(operationLabel);lineFields.append(qtyLabel);const manual=select.value==='manual';titleLabel.hidden=!manual;f('title').required=manual;select.required=!manual;priceLabel.hidden=!product;price.required=!!product;}else{box.before(operationLabel);amountRow.prepend(qtyLabel);select.required=false;price.required=false;}}
 function recalculate(){if(box.hidden||!PRODUCTS.some(p=>p.id===select.value))return;try{const unit=cents(price.value),qty=Number(f('qty').value),total=lineTotal(unit,qty);f('amount').value=(total/100).toFixed(2);hint.textContent=rub(unit)+' × '+qty+' шт. = '+rub(total);}catch(e){hint.textContent=e.message;}}
 select.onchange=()=>{selectedId=select.value;const product=PRODUCTS.find(p=>p.id===selectedId);if(product){f('title').value=product.title;f('article').value=product.article;price.value=(product.unitPrice/100).toFixed(2);recalculate();}else{f('title').value='';f('article').value='';price.value='';hint.textContent='';}show();};
 search.oninput=options;price.oninput=recalculate;f('qty').addEventListener('input',recalculate);
 f('amount').addEventListener('input',()=>{if(!box.hidden&&PRODUCTS.some(p=>p.id===select.value))hint.textContent='Итог можно изменить, например при скидке.';});
 options();show();
 return {show,reset(entry){search.value='';const product=entry?.type==='sale'?PRODUCTS.find(p=>p.id===entry.catalogId):null;selectedId=product?product.id:entry?'manual':'';options();price.value=product?((entry.unitPrice??product.unitPrice)/100).toFixed(2):'';hint.textContent=product?'Сохраненная сумма: '+rub(entry.amount):'';show();},decorate(item){if(item.type!=='sale')return;const product=PRODUCTS.find(p=>p.id===select.value);if(!product)return;const unit=cents(price.value);lineTotal(unit,item.qty);item.catalogId=product.id;item.unitPrice=unit;item.priceAdjusted=lineTotal(unit,item.qty)!==item.amount;}};
}
